\label{prop:anathema}
For $j=1$ (exterior) and $j=2$ (interior), the following properties hold:
 \[
  {\cal A}^{(j)}_{\rm SL} \in\mathrm{OPS}(0), \quad
  {\cal C}^{(j)}_{\rm SL},\ {\cal A}^{(j)}_{\rm DL} \in\mathrm{OPS}(1),\quad
  {\cal C}^{(j)}_{\rm DL} \in\mathrm{OPS}(2).
 \]
 Furthermore,
 \[
 \begin{aligned}
  {\cal A}^{(j)}_{\rm SL} =&\frac{(-1)^{j}}{2}{\cal H}^{(j)} +
                                 \frac{1}4
                                  \begin{bmatrix}
                                       &(k_s^{(j)})^2 \operatorname{H}\\
                                    (k_p^{(j)})^2 \operatorname{H} &
                                   \end{bmatrix} (\operatorname{H} \mathrm{D}_{-1})^2
+\mathrm{OPS}(-3),\\
   {\cal A}^{(j)}_{\rm DL}  =&   \frac{1}{2} {\cal H}^{(j)}\operatorname{H}\mathrm{D}

  +\frac{1}{4}
\begin{bmatrix}
 (k_p^{(j)})^2\operatorname{I} & \\
                        & -(k_s^{(j)})^2\operatorname{I}
\end{bmatrix}  \operatorname{H} \mathrm{D}_{-1} +{\mathrm{OPS}(-2)},
\\
 {\cal C}^{(j)}_{\rm SL}
    = &   -\mu_j{\cal H}^{(j)} \operatorname{H}\mathrm{D}
                  -\mu_{j}\kappa(-1)^{j} 
                  {\cal H}^{(j)}




+{\mathrm{OPS}(-1)},








                                     \\
{\cal C}^{(j)}_{\rm DL}=&
 (-1)^{j+1}\mu_j{\cal H}^{(j)} (\operatorname{H}\mathrm{D})^2
                                   -\mu_j\kappa {\cal H}^{(j)}\operatorname{H}\mathrm{D}




+ \mathrm{OPS}(0),
\end{aligned}
 \]
 with
 \[
  {\cal H}^{(j)} := \begin{bmatrix}
                                     \operatorname{I} &(-1)^{j }\operatorname{H}\\
                                    (-1)^{j }\operatorname{H} & - \operatorname{I}
                                   \end{bmatrix}.
 \]

\label{theo:transmission:helmholtz} 
  Let $k_1, k_2>0$, $\{\operatorname{V}_{k_j},\operatorname{K}_{k_j},\operatorname{K}_{k_j}^\top,  \operatorname{W}_{k_j}\}$, $j=1,2$ be the Helmholtz boundary integral operators associated with wavenumbers $k_1$ and $k_2$. Then, for any $\alpha\ne 0$ and $\rho>0$, the operator ${\cal L}_{\alpha,\rho}:H^s (\Gamma)\times H^{s-1}(\Gamma) \to H^s(\Gamma)\times H^{s-1}(\Gamma)$ given by
\begin{equation}\label{eq:Lformulation}
{\cal L}_{\alpha,\rho}\begin{bmatrix}
g\\
\varphi\\
\end{bmatrix}:= 
\frac{1}2 \begin{bmatrix}
(1-\alpha)g\\
(1-\alpha\rho )\varphi\\
\end{bmatrix} +\begin{bmatrix}
{\rm K}_{k_1}+\alpha {\rm K}_{k_2} & -{\rm V}_{k_1}-\alpha {\rm V}_{k_2}\\
{\rm W}_{k_1}+\alpha\rho {\rm W}_{k_2} & -{\rm K}^\top_{k_1}-\alpha  \rho{\rm K}^\top_{k_2}\\
\end{bmatrix} \begin{bmatrix}
g\\
\varphi\\
\end{bmatrix} 
\end{equation}
is invertible.

\label{theo:01}
Define
\[
\begin{aligned}
\mathfrak{P}^{\rm left} &\ : = \mathfrak{A}^{\rm left}_{6} \mathfrak{A}^{\rm left}_{5} \mathfrak{A}^{\rm left}_{4}
  \mathfrak{A}^{\rm left}_{3}
\mathfrak{A}^{\rm left}_{2}\mathfrak{A}^{\rm left}_{1},\\
\mathfrak{P}^{\rm right}&\ :=
 \begin{bmatrix*}
{\cal I} & 0\\
       0  & \begin{bmatrix*}[r]
         0&-(\mathrm{D} +\operatorname{J})^{-1}\\
         (\mathrm{D}+\operatorname{J})^{-1}& 0\\
         \end{bmatrix*} 
        \end{bmatrix*}=
        \mathfrak{A}_1^{\rm right} \mathfrak{A}_2^{\rm right} +{\rm OPS}(-\infty).
\end{aligned}
\]
Then  $ \mathfrak{P}^{\rm left}  \mathfrak{A}_\alpha  \mathfrak{P}^{\rm right} : {\cal H}^{s}(\Gamma)\times {\cal H}^{s}(\Gamma)\to {\cal H}^{s}(\Gamma)\times {\cal H}^{s}(\Gamma)$ is continuous and invertible. Moreover,   $\mathfrak{P}^{\rm left}  \mathfrak{A}_\alpha  \mathfrak{P}^{\rm right}$ is a compact perturbation of the identity, i.e.,
\begin{equation}\label{eq:01:theo:01}
  \mathfrak{P}^{\rm left}  \mathfrak{A}_\alpha  \mathfrak{P}^{\rm right} =
\mathfrak{I}+{\rm OPS}(-1).
\end{equation}

\label{cor:01}
  The equation in the original (unpreconditioned) $(\bm{n},\bm{t})$-CFIE$_\alpha$ formulation 
 \begin{equation}\label{eq:cfie_t:2}
\mathfrak{A}_{\alpha}
\begin{bmatrix}
{\bm \varphi}\\
{\bm g}
\end{bmatrix}
=
\begin{bmatrix}
{\bm f}\\
{\bm \lambda}
\end{bmatrix}
\end{equation}
is uniquely solvable. Furthermore, if $(\bm{f},\bm{\lambda})\in {\cal H}^{s+1}(\Gamma)\times {\cal H}^{s}(\Gamma)$, then the solution $(\bm{\varphi},\bm{g})$ belongs to ${\cal H}^{s-1}(\Gamma)\times {\cal H}^{s}(\Gamma)$ and satisfies the estimate, with $C$ independent of the data.                          
\[
\|\bm{\varphi}\|_{{\cal H}^{s-1}(\Gamma)}+
\|\bm{g}\|_{{\cal H}^{s}(\Gamma)}
\le
C\Big(
\|\bm{f}\|_{{\cal H}^{s+1}(\Gamma)}+\|\bm{\lambda}\|_{{\cal H}^{s}(\Gamma)}
\Big).
\]

Existence follows from Theorem \ref{theo:01} and \eqref{eq:step:A3}; uniqueness was proven in Theorem~\ref{theo:unicity}.  

By construction,
\begin{align}
  \mathfrak{P}^{\mathrm{left}} &: \
  \mathcal{H}^{s+1}(\Gamma)\times \mathcal{H}^{s}(\Gamma)\to \mathcal{H}^{s-1}(\Gamma)\times \mathcal{H}^{s-1}(\Gamma), 
  \label{eq:prop:P:01}\\
     \left(\mathfrak{P}^{\mathrm{left}} \mathfrak{A}_\alpha   \mathfrak{P}^{\mathrm{right}}\right)^{-1}&: 
   \mathcal{H}^{s-1}(\Gamma)\times \mathcal{H}^{s-1}(\Gamma)\to \mathcal{H}^{s-1}(\Gamma)\times \mathcal{H}^{s-1}(\Gamma),\label{eq:prop:P:02}\\
  \mathfrak{P}^{\mathrm{right}}&:\mathcal{H}^{s-1}(\Gamma)\times \mathcal{H}^{s-1}(\Gamma)\to \mathcal{H}^{s-1}(\Gamma)\times \mathcal{H}^{s}(\Gamma)\label{eq:prop:P:03}
\end{align}
 are continuous for all $s$ with continuity constants independent of the data and denoted by $C_{\mathfrak{P}^{\rm left}}$, $C$ and $C_{\mathfrak{P}^{\rm right}}$ respectively. We stress that $\mathfrak P^{\rm left}$ acts on the data in the order $(\bm f,\bm\lambda)$ of \eqref{eq:step:A1} and $\mathfrak P^{\rm right}$ on the unknowns in the order $(\check{\bm\varphi},\check{\bm g})$ of \eqref{eq:step:A3}; in the estimates below the order of the norms is immaterial, but the Sobolev index attached to each function is not.


Now  \begin{align*}
\|{\bm{\varphi}}\|_{\mathcal{H}^{s-1}(\Gamma)}+
  \|{\bm{g}}\|_{\mathcal{H}^{s}(\Gamma)}
 &\ \le C_{ \mathfrak{P}^{\rm right}}\left[ 
\|\check{\bm{\varphi}}\|_{\mathcal{H}^{s-1}(\Gamma)}+\| \check{\bm{g}}\|_{\mathcal{H}^{s-1}(\Gamma)}
 \right]\tag*{(by  \eqref{eq:step:A3} and  \eqref{eq:prop:P:03})}\\
&\ \le  C_{ \mathfrak{P}^{\rm right}} \,C\, \left[
\|\check{\bm{f}}\|_{\mathcal{H}^{s-1}(\Gamma)}+\|\check{\bm{\lambda}}\|_{\mathcal{H}^{s-1}(\Gamma)}
\right]\tag*{(by  \eqref{eq:step:A2} and  \eqref{eq:prop:P:02})}\\ 
&\ \le
C_{ \mathfrak{P}^{\rm right}} \,C  \, C_{ \mathfrak{P}^{\rm left}}\left[
\|\bm{f}\|_{\mathcal{H}^{s+1}(\Gamma)}+\| {\bm{\lambda}}\|_{\mathcal{H}^{s}(\Gamma)} \right]. \tag*{(by   
\eqref{eq:step:A1} and \eqref{eq:prop:P:01})}
\end{align*}
which proves the result.
